Since you didn't specify which shape you want to calculate the area for, here is a versatile Python script that calculates the area of a **rectangle**, **circle**, or **triangle** based on user input.

```python
import math

def calculate_rectangle_area(length, width):
    return length * width

def calculate_circle_area(radius):
    return math.pi * (radius ** 2)

def calculate_triangle_area(base, height):
    return 0.5 * base * height

def main():
    print("Area Calculator")
    print("Please select a shape:")
    print("1. Rectangle")
    print("2. Circle")
    print("3. Triangle")

    while True:
        choice = input("Enter the number of your choice (1/2/3): ")

        if choice in ['1', '2', '3']:
            break
        else:
            print("Invalid choice. Please enter 1, 2, or 3.")

    try:
        if choice == '1':
            length = float(input("Enter the length of the rectangle: "))
            width = float(input("Enter the width of the rectangle: "))
            area = calculate_rectangle_area(length, width)
            print(f"The area of the rectangle is: {area:.2f}")

        elif choice == '2':
            radius = float(input("Enter the radius of the circle: "))
            area = calculate_circle_area(radius)
            print(f"The area of the circle is: {area:.2f}")

        elif choice == '3':
            base = float(input("Enter the base of the triangle: "))
            height = float(input("Enter the height of the triangle: "))
            area = calculate_triangle_area(base, height)
            print(f"The area of the triangle is: {area:.2f}")

    except ValueError:
        print("Error: Please enter valid numeric values.")

if __name__ == "__main__":
    main()
```

### How to use it:
1. Run the script using Python (`python area_calculator.py`).
2. It will prompt you to choose a shape (1 for Rectangle, 2 for Circle, 3 for Triangle).
3. Enter the required dimensions.
4. The script will calculate and print the area rounded to two decimal places. It also includes error handling just in case you accidentally type a letter instead of a number.
